#!/usr/bin/env python3
import csv, json, os, re, sys
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal

DAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]


def read_text(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        return f.read()


def read_csv(path):
    import io
    rows = csv.DictReader(io.StringIO(read_text(path), newline=""))
    out = []
    for r in rows:
        out.append({(k or "").strip().lstrip("\ufeff"): (v if v is not None else "") for k, v in r.items()})
    return out


def cents(s):
    return int((Decimal(s.strip()) * 100).to_integral_value())


def pdate(s):
    return date.fromisoformat(s.strip())


def digits(s):
    return int(re.sub(r"\D", "", s) or "0")


def parse_offset(s):
    m = re.fullmatch(r"\s*([+-])(\d\d):?(\d\d)\s*", s)
    mins = int(m.group(2)) * 60 + int(m.group(3))
    return timedelta(minutes=-mins if m.group(1) == "-" else mins)


def parse_policy(path):
    secs = {}
    cur = None
    for line in read_text(path).splitlines():
        line = line.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            cur = line[1:-1].strip()
            secs[cur] = {}
        elif "=" in line and cur is not None:
            k, v = line.split("=", 1)
            secs[cur][k.strip().lower()] = v.strip()
    return secs


def main(inp, outp):
    pol = parse_policy(os.path.join(inp, "policy.ini"))
    library = pol["statement"]["library"]
    pstart = pdate(pol["statement"]["period_start"])
    pend = pdate(pol["statement"]["period_end"])
    clock = pol.get("clock", {})
    base_off = parse_offset(clock.get("offset", "+00:00"))
    changes = []
    for part in clock.get("changes", "").split(";"):
        part = part.strip()
        if not part:
            continue
        ts, off = part.split(None, 1)
        t = datetime.strptime(ts, "%Y-%m-%dT%H:%MZ").replace(tzinfo=timezone.utc)
        changes.append((t, parse_offset(off)))
    changes.sort()

    items = {}
    cats = {}
    for name, d in pol.items():
        if name.lower().startswith("item:"):
            items[name[5:].strip().lower()] = (name[5:].strip(), {
                "loan_days": int(d["loan_days"]), "renewals": int(d["renewals"]),
                "grace": int(d["grace_days"]), "daily": cents(d["daily"]),
                "loan_cap": cents(d["loan_cap"])})
        elif name.lower().startswith("category:"):
            sc = d.get("statement_cap", "none").strip().lower()
            cats[name[9:].strip().lower()] = (name[9:].strip(), {
                "cap": None if sc == "none" else cents(sc),
                "discount": int(d.get("discount", "0") or 0),
                "exempt": {x.strip().lower() for x in d.get("exempt", "").split(",") if x.strip()}})

    branches = read_csv(os.path.join(inp, "branches.csv"))
    bids = {}
    open_days = {}
    for b in branches:
        bid = b["branch"].strip()
        bids[bid.lower()] = bid
        open_days[bid] = {w.lower()[:3] for w in b["open_days"].split()}

    cal_branch = {}
    cal_star = {}
    for r in read_csv(os.path.join(inp, "calendar.csv")):
        ds = r["date"].strip()
        if not ds:
            continue
        if ".." in ds:
            a, z = ds.split("..")
            a, z = pdate(a), pdate(z)
        else:
            a = z = pdate(ds)
        st = r["status"].strip().lower()
        br = r["branch"].strip()
        n = (z - a).days
        for i in range(n + 1):
            day = a + timedelta(days=i)
            if br == "*":
                cal_star[day] = st
            else:
                cal_branch[(bids.get(br.lower(), br), day)] = st

    def is_open(b, day):
        s = cal_branch.get((b, day))
        if s is None:
            s = cal_star.get(day)
        if s is not None:
            return s == "open"
        return DAYS[day.weekday()] in open_days.get(b, set())

    def next_open(b, day):
        for _ in range(4000):
            if is_open(b, day):
                return day
            day += timedelta(days=1)
        return day

    patrons = {}
    for r in read_csv(os.path.join(inp, "patrons.csv")):
        patrons.setdefault(digits(r["patron"]), []).append((pdate(r["since"]), r["patron"].strip(), r["category"].strip()))
    for v in patrons.values():
        v.sort(key=lambda x: x[0])

    def cat_on(pn, day):
        rows = patrons[pn]
        cur = rows[0]
        for r in rows:
            if r[0] <= day:
                cur = r
        return cats[cur[2].lower()]

    waivers = []
    for r in read_csv(os.path.join(inp, "waivers.csv")):
        if r["status"].strip().lower() != "active":
            continue
        v = r["value"].strip()
        waivers.append((digits(r["patron"]), r["loan"].strip(), None if v.lower() == "full" else cents(v)))

    # events
    exdir = os.path.join(inp, "exports")
    events = {}
    for fn in sorted(os.listdir(exdir)):
        if not (fn.endswith(".csv") or fn.endswith(".jsonl")):
            continue
        path = os.path.join(exdir, fn)
        if not os.path.isfile(path):
            continue
        if fn.endswith(".csv"):
            recs = read_csv(path)
            for r in recs:
                r = {k: (v.strip() if v else None) or None for k, v in r.items()}
                t = r.get("time")
                r["local"] = datetime.strptime(t, "%Y-%m-%d %H:%M") if t else None
                events.setdefault(r["event"], r)
        else:
            for line in read_text(path).splitlines():
                if not line.strip():
                    continue
                r = json.loads(line)
                r = {k: (str(v).strip() if v is not None and str(v).strip() != "" else None) for k, v in r.items()}
                at = r["at"]
                m = re.fullmatch(r"(\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d)(?:\.\d+)?(Z|[+-]\d\d:?\d\d)", at)
                dt = datetime.strptime(m.group(1), "%Y-%m-%dT%H:%M:%S")
                off = timedelta(0) if m.group(2) == "Z" else parse_offset(m.group(2))
                utc = (dt - off).replace(tzinfo=timezone.utc)
                lo = base_off
                for ct, co in changes:
                    if ct <= utc:
                        lo = co
                r["local"] = (utc + lo).replace(tzinfo=None)
                events.setdefault(r["event"], r)

    cancelled = set()
    for e in events.values():
        if (e.get("type") or "").lower() == "void" and e.get("target"):
            cancelled.add(e["target"])

    loans = {}
    follow = {}
    for e in events.values():
        if e["event"] in cancelled:
            continue
        ty = (e.get("type") or "").lower()
        if ty == "checkout":
            loans[e["loan"]] = e
        elif ty in ("renew", "return"):
            follow.setdefault(e["loan"], []).append((e["local"], ty, e))

    stmts = {}
    for lid, c in loans.items():
        cod = c["local"].date()
        if cod > pend:
            continue
        itname, it = items[c["item_type"].lower()]
        cb = bids.get(c["branch"].lower(), c["branch"])
        due = next_open(cb, cod + timedelta(days=it["loan_days"]))
        nren = 0
        ret = None
        for lt, ty, e in sorted(follow.get(lid, []), key=lambda x: x[0]):
            d = lt.date()
            if ty == "renew":
                if d <= due and nren < it["renewals"] and d <= pend:
                    nren += 1
                    due = next_open(cb, d + timedelta(days=it["loan_days"]))
            else:
                ret = d - timedelta(days=1) if (e.get("via") or "").lower() == "dropbox" else d
                break
        if ret is not None and ret < pstart:
            continue
        returned = ret if ret is not None and ret <= pend else None
        end = returned or pend
        od = 0
        day = due + timedelta(days=1)
        while day <= end:
            if is_open(cb, day):
                od += 1
            day += timedelta(days=1)
        if od < 1:
            continue
        pn = digits(c["patron"])
        cat = cat_on(pn, cod)
        charged = od if od > it["grace"] else 0
        fee = charged * it["daily"]
        if itname.lower() in cat[1]["exempt"]:
            fee = 0
        fee = min(fee, it["loan_cap"])
        fee = (fee * (100 - cat[1]["discount"]) + 50) // 100
        stmts.setdefault(pn, []).append({
            "loan": lid, "item": c["item"], "item_type": itname, "branch": cb,
            "checkout": cod.isoformat(), "due": due.isoformat(),
            "returned": returned.isoformat() if returned else None,
            "overdue_days": od, "charged_days": charged, "assessed": fee,
            "waived": 0, "capped": 0, "billed": 0, "_due": due})

    out_st = []
    for pn in sorted(stmts):
        ls = sorted(stmts[pn], key=lambda l: (l["_due"], l["loan"]))
        ws = [w for w in waivers if w[0] == pn]
        for l in ls:
            ap = [w for w in ws if w[1] == "*" or w[1] == l["loan"]]
            if any(w[2] is None for w in ap):
                l["waived"] = l["assessed"]
            else:
                l["waived"] = min(sum(w[2] for w in ap), l["assessed"])
        catname, cat = cat_on(pn, pend) if False else (None, None)
        cname, cat = cat_on(pn, pend)
        if cat["cap"] is not None:
            excess = sum(l["assessed"] - l["waived"] for l in ls) - cat["cap"]
            for l in sorted(ls, key=lambda l: (l["_due"], l["loan"]), reverse=True):
                if excess <= 0:
                    break
                g = min(excess, l["assessed"] - l["waived"])
                l["capped"] = g
                excess -= g
        for l in ls:
            l["billed"] = l["assessed"] - l["waived"] - l["capped"]
        row = max((r for r in patrons[pn] if r[0] <= pend), key=lambda r: r[0], default=patrons[pn][0])
        s = {"patron": row[1], "category": cname, "loans": ls}
        for k in ("assessed", "waived", "capped", "billed"):
            s[k] = sum(l[k] for l in ls)
        out_st.append(s)

    summary = []
    for b in branches:
        bid = b["branch"].strip()
        r = {"branch": bid, "loans": 0, "charged_days": 0, "assessed": 0, "waived": 0, "capped": 0, "billed": 0}
        for s in out_st:
            for l in s["loans"]:
                if l["branch"] == bid:
                    r["loans"] += 1
                    for k in ("charged_days", "assessed", "waived", "capped", "billed"):
                        r[k] += l[k]
        summary.append(r)
    for s in out_st:
        for l in s["loans"]:
            del l["_due"]
    res = {"library": library, "period": {"start": pstart.isoformat(), "end": pend.isoformat()},
           "statements": out_st, "branches": summary}
    with open(outp, "w", encoding="utf-8") as f:
        json.dump(res, f, indent=2, ensure_ascii=False)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
